CREATE TABLE "Role"("roleid" SERIAL PRIMARY KEY,"rolename" VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE "Membership"("mid" SERIAL PRIMARY KEY,"mname" VARCHAR(50) NOT NULL UNIQUE,"score" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "User"("uid" SERIAL PRIMARY KEY,"username" VARCHAR(50) NOT NULL UNIQUE,"fullname" VARCHAR(100) NOT NULL,"password" VARCHAR(255) NOT NULL,"roleid" INTEGER NOT NULL REFERENCES "Role"("roleid") ON DELETE RESTRICT ON UPDATE CASCADE,"mid" INTEGER NOT NULL REFERENCES "Membership"("mid") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Product"("pid" SERIAL PRIMARY KEY,"pname" VARCHAR(100) NOT NULL,"price" DECIMAL(10,2) NOT NULL,"quantity" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "Order"("oid" SERIAL PRIMARY KEY,"uid" INTEGER NOT NULL REFERENCES "User"("uid") ON DELETE RESTRICT ON UPDATE CASCADE,"createat" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Order_uid_createat_idx" ON "Order"("uid","createat");
CREATE TABLE "OrderDetail"("oid" INTEGER NOT NULL REFERENCES "Order"("oid") ON DELETE CASCADE ON UPDATE CASCADE,"pid" INTEGER NOT NULL REFERENCES "Product"("pid") ON DELETE RESTRICT ON UPDATE CASCADE,"qty" INTEGER NOT NULL,"unit_price" DECIMAL(10,2) NOT NULL,PRIMARY KEY("oid","pid"));
CREATE TABLE "Shipment"("shipid" SERIAL PRIMARY KEY,"oid" INTEGER NOT NULL REFERENCES "Order"("oid") ON DELETE CASCADE ON UPDATE CASCADE,"status" VARCHAR(50) NOT NULL);
CREATE INDEX "Shipment_oid_idx" ON "Shipment"("oid");
